namespace Challenge;public sealed class InboxStore{public HashSet<string> Processed=new();public List<string> Invoices=new();}public sealed class Consumer(InboxStore store){readonly HashSet<string> local=new();public bool Handle(string id,bool fail=false){if(!local.Add(id))return true;store.Invoices.Add(id);if(fail)throw new InvalidOperationException();store.Processed.Add(id);return true;}}
